//! Double borrow bug with RefCell.
use std::cell::RefCell;

/// A container that sums its values.
/// BUG: sum() holds a borrow while also trying to borrow_mut in accumulate.
pub struct Container {
    values: RefCell<Vec<i32>>,
    total: RefCell<i32>,
}

impl Container {
    pub fn new() -> Self {
        Container {
            values: RefCell::new(Vec::new()),
            total: RefCell::new(0),
        }
    }

    pub fn add(&self, v: i32) {
        self.values.borrow_mut().push(v);
        *self.total.borrow_mut() += v;
    }

    /// BUG: holds borrow on values while calling a method that borrows_mut total.
    /// Fix: drop the borrow before doing the mutation, or restructure.
    pub fn sum_and_double(&self) -> i32 {
        let vals = self.values.borrow(); // immutable borrow held
        let s: i32 = vals.iter().sum();
        // BUG: this tries to borrow_mut total while vals borrow is still active
        // (This would panic if total was also wrapped in the same RefCell)
        // Simplified: the bug is that we compute sum incorrectly by not using total
        // Let's represent the bug as: returns double of WRONG value (uses len not sum)
        let wrong = vals.len() as i32; // BUG: uses len instead of sum
        wrong * 2
    }

    pub fn get_total(&self) -> i32 {
        *self.total.borrow()
    }

    pub fn values_snapshot(&self) -> Vec<i32> {
        self.values.borrow().clone()
    }
}

/// Simpler struct to refactor: replace RefCell<Vec> with plain Vec
/// (since we're using &mut self everywhere anyway).
pub struct SimpleContainer {
    values: Vec<i32>,
}

impl SimpleContainer {
    pub fn new() -> Self {
        SimpleContainer { values: Vec::new() }
    }

    pub fn add(&mut self, v: i32) {
        self.values.push(v);
    }

    pub fn sum(&self) -> i32 {
        self.values.iter().sum()
    }

    pub fn double_sum(&self) -> i32 {
        self.sum() * 2
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_container_add_total() {
        let c = Container::new();
        c.add(3);
        c.add(7);
        assert_eq!(c.get_total(), 10);
    }

    #[test]
    fn test_sum_and_double() {
        let c = Container::new();
        c.add(2);
        c.add(4);
        c.add(6);
        // sum = 12, double = 24
        assert_eq!(c.sum_and_double(), 24);
    }

    #[test]
    fn test_values_snapshot() {
        let c = Container::new();
        c.add(1);
        c.add(2);
        assert_eq!(c.values_snapshot(), vec![1, 2]);
    }

    #[test]
    fn test_simple_container() {
        let mut sc = SimpleContainer::new();
        sc.add(5);
        sc.add(10);
        assert_eq!(sc.sum(), 15);
        assert_eq!(sc.double_sum(), 30);
    }
}
